ALTER TABLE public.civic_coverage ADD COLUMN IF NOT EXISTS settings jsonb NOT NULL DEFAULT '{}'::jsonb, ADD COLUMN IF NOT EXISTS reporting_enabled boolean NOT NULL DEFAULT true;
ALTER TABLE public.issues ADD COLUMN IF NOT EXISTS coverage_id text REFERENCES public.civic_coverage(id);
UPDATE public.issues SET coverage_id= routing_snapshot->'coverage'->>'id' WHERE coverage_id IS NULL AND EXISTS(SELECT 1 FROM public.civic_coverage c WHERE c.id=issues.routing_snapshot->'coverage'->>'id');
ALTER TABLE public.civic_teams ADD COLUMN IF NOT EXISTS coverage_id text REFERENCES public.civic_coverage(id) DEFAULT 'bengaluru';
ALTER TABLE public.staff_profiles ADD COLUMN IF NOT EXISTS coverage_ids text[] NOT NULL DEFAULT ARRAY['bengaluru']::text[];
ALTER TABLE public.admin_permissions ADD COLUMN IF NOT EXISTS coverage_ids text[] NOT NULL DEFAULT ARRAY['bengaluru']::text[];
ALTER TABLE public.civic_people ADD COLUMN IF NOT EXISTS coverage_id text REFERENCES public.civic_coverage(id), ADD COLUMN IF NOT EXISTS jurisdiction text, ADD COLUMN IF NOT EXISTS office_address text;
UPDATE public.civic_people SET coverage_id='bengaluru' WHERE coverage_id IS NULL;
CREATE INDEX IF NOT EXISTS issues_coverage_idx ON public.issues(coverage_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.can_access_service_area(_user uuid,_area text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_active(_user) AND _area IS NOT NULL AND (EXISTS(SELECT 1 FROM public.admin_permissions a WHERE a.user_id=_user AND public.has_role(_user,'admin') AND (a.is_super_admin OR _area=ANY(a.coverage_ids))) OR EXISTS(SELECT 1 FROM public.staff_profiles p WHERE p.user_id=_user AND p.active AND _area=ANY(p.coverage_ids))) $$;
REVOKE ALL ON FUNCTION public.can_access_service_area(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.can_access_service_area(uuid,text) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.staff_can_work(_user_id uuid,_issue uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) AND EXISTS(SELECT 1 FROM public.issues i WHERE i.id=_issue AND public.can_access_service_area(_user_id,i.coverage_id) AND (public.has_role(_user_id,'admin') OR EXISTS(SELECT 1 FROM public.staff_profiles p LEFT JOIN public.civic_teams t ON t.id=i.team_id WHERE p.user_id=_user_id AND p.demo_dataset_id IS NOT DISTINCT FROM i.demo_dataset_id AND p.active AND public.staff_configuration_valid(_user_id) AND (i.team_id IS NULL OR (t.active AND t.coverage_id=i.coverage_id)) AND public.staff_scope_matches(p.department,p.categories,p.wards,p.team_ids,p.corporations,i.category,coalesce(t.department,i.department),i.team_id,i.routing_snapshot->'ward'->>'identifier',i.routing_snapshot->'ward'->>'corporation')))) $$;
CREATE OR REPLACE FUNCTION public.persist_issue_service_area() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE resolved text; BEGIN resolved:=NEW.routing_snapshot->'coverage'->>'id'; IF TG_OP='UPDATE' AND OLD.coverage_id IS NOT NULL AND (NEW.coverage_id IS DISTINCT FROM OLD.coverage_id OR resolved IS DISTINCT FROM OLD.routing_snapshot->'coverage'->>'id') THEN RAISE EXCEPTION 'Original report service area is immutable'; END IF; IF TG_OP='INSERT' THEN IF NOT EXISTS(SELECT 1 FROM civic_coverage c WHERE c.id=resolved AND c.enabled AND c.reporting_enabled) THEN RAISE EXCEPTION 'Verified reporting service area required'; END IF; NEW.coverage_id:=resolved; END IF; IF NEW.team_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM civic_teams t WHERE t.id=NEW.team_id AND t.coverage_id=NEW.coverage_id) THEN RAISE EXCEPTION 'Team belongs to a different service area'; END IF; RETURN NEW; END $$;
CREATE TRIGGER issue_service_area_guard BEFORE INSERT OR UPDATE ON public.issues FOR EACH ROW EXECUTE FUNCTION public.persist_issue_service_area();
DO $patch$ DECLARE s text; BEGIN s:=pg_get_functiondef('public.route_issue_to_team(uuid)'::regprocedure); IF position('demo_dataset_id IS NOT DISTINCT FROM v.demo_dataset_id' in s)=0 THEN RAISE EXCEPTION 'Routing signature mismatch'; END IF; s:=replace(s,'WHERE demo_dataset_id IS NOT DISTINCT FROM v.demo_dataset_id','WHERE coverage_id=v.coverage_id AND demo_dataset_id IS NOT DISTINCT FROM v.demo_dataset_id'); EXECUTE s; END $patch$;
CREATE OR REPLACE FUNCTION public.public_area_case_rows(_area text,_include_demo boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(row),'[]'::jsonb) FROM (SELECT i.id,i.ref_code,i.title,i.summary,i.description,i.category,i.subcategory,i.severity,i.status,i.safety_warning,i.lat,i.lng,i.landmark,i.photo_url,i.department,i.support_count,i.sla_due_at,i.resolved_at,i.created_at,i.updated_at,i.duplicate_of,i.duplicate_candidate_id,i.routing_snapshot,i.acknowledged_at,i.ack_message,i.eta_at,i.inspection_at,i.coverage_id,CASE WHEN i.acknowledged_by IS NULL THEN NULL ELSE public.staff_actor_label(i.acknowledged_by) END acknowledged_by_label FROM issues i WHERE i.coverage_id=_area AND (_include_demo OR i.demo_dataset_id IS NULL) ORDER BY i.created_at DESC LIMIT 1000) row $$;
REVOKE ALL ON FUNCTION public.public_area_case_rows(text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_area_case_rows(text,boolean) TO anon,authenticated,service_role;
DO $patch$ DECLARE s text; BEGIN s:=pg_get_functiondef('public.public_report_snapshot(jsonb)'::regprocedure); s:=replace(s,'AND (start_at IS NULL OR i.created_at>=start_at)','AND (coalesce(_filters->>''coverage_id'','''')='''' OR i.coverage_id=_filters->>''coverage_id'') AND (start_at IS NULL OR i.created_at>=start_at)'); EXECUTE s; END $patch$;
CREATE OR REPLACE FUNCTION public.admin_save_service_area(_id text,_name text,_settings jsonb,_bounds jsonb,_source text,_reporting boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR NOT EXISTS(SELECT 1 FROM admin_permissions WHERE user_id=auth.uid() AND is_super_admin) THEN RAISE EXCEPTION 'Super Admin required'; END IF; IF length(trim(_name))<2 OR _id !~ '^[a-z0-9-]{2,60}$' OR _source NOT LIKE 'https://%' THEN RAISE EXCEPTION 'Valid area and source required'; END IF; IF _reporting AND NOT EXISTS(SELECT 1 FROM civic_wards WHERE coverage_id=_id AND active AND verification_status='verified') THEN RAISE EXCEPTION 'Verified jurisdiction polygons required before activating reports'; END IF; UPDATE civic_coverage SET name=_name,settings=_settings,bounds=_bounds,source_url=_source,reporting_enabled=_reporting WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Configured service area not found'; END IF; INSERT INTO civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('civic_coverage',gen_random_uuid(),'service_area_updated',auth.uid(),jsonb_build_object('coverage_id',_id,'reporting_enabled',_reporting,'settings',_settings)); END $$;
REVOKE ALL ON FUNCTION public.admin_save_service_area(text,text,jsonb,jsonb,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_save_service_area(text,text,jsonb,jsonb,text,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_set_area_scope(_user uuid,_areas text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR NOT EXISTS(SELECT 1 FROM admin_permissions WHERE user_id=auth.uid() AND is_super_admin) THEN RAISE EXCEPTION 'Super Admin required'; END IF; IF cardinality(_areas)=0 OR EXISTS(SELECT 1 FROM unnest(_areas) a WHERE NOT EXISTS(SELECT 1 FROM civic_coverage c WHERE c.id=a AND c.enabled)) THEN RAISE EXCEPTION 'Configured areas required'; END IF; UPDATE staff_profiles SET coverage_ids=_areas,updated_at=now(),updated_by=auth.uid() WHERE user_id=_user; INSERT INTO civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('staff_profiles',_user,'service_area_scope',auth.uid(),jsonb_build_object('coverage_ids',_areas)); END $$;
REVOKE ALL ON FUNCTION public.admin_set_area_scope(uuid,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_set_area_scope(uuid,text[]) TO authenticated;